// Buying straight onto the board: one snapshot, two engine actions, one render.
function buyInto(index,zone,position,rect,html){const before=captureState(),bought=act(game,{type:'buy',index});if(!bought.ok){toast(bought.message,{error:true});return;}const fresh=game.units.find(u=>!before.units.has(u.uid));let note=bought.message;if(fresh&&(zone!=='bench'||position!==undefined)){const moved=act(game,{type:'move',uid:fresh.uid,zone,position});if(!moved.ok)note=`${bought.message} · ${moved.message}`;}save();settle(before,{type:'buy'},fresh?{dragUid:fresh.uid,dragRect:rect}:{shopRect:rect,shopHtml:html});toast(note);}

// Styled tooltips for anything carrying data-tip / data-tip-kind.
