let tipTarget=null,tipTimer=null;
function tipContent(el){const kind=el.dataset.tipKind,id=el.dataset.tipId,extra=el.dataset.tipExtra?`<em>${esc(el.dataset.tipExtra)}</em>`:'';
 if(kind==='item'){const e=getEquipment(id);if(!e)return '';const recipe=Object.entries(RECIPES).find(([,out])=>out===(e.baseId||e.id))?.[0];return `<strong>${itemArt(e.id,'tip-art')}${esc(e.name)}</strong><small>${e.privileged?'特权装备':e.craftingMaterial?'特殊材料':e.tier===1?'简易装备':'进阶装备'}${e.unique?' · 唯一':''}</small><p>${esc(e.description)}</p>${recipe?`<p class="tip-recipe">${recipe.split('+').map(x=>esc(getEquipment(x)?.name||x)).join(' ＋ ')}</p>`:''}${extra}`;}
 if(kind==='trait'){const t=TRAITS.find(t=>t.id===id),s=getSynergies(game).find(s=>s.id===id);if(!t)return '';return `<strong>${traitArt(id)}${esc(t.name)} <b>${s?.count||0}</b></strong><p>${esc(getClassicTraitSimulationDescription(t.id)||t.description)}</p><ul class="tip-levels">${t.levels.map(l=>`<li class="${(s?.count||0)>=l.count?'on':''}"><b>${l.count}</b>${esc(l.description)}</li>`).join('')}</ul>${extra}`;}
 const title=el.dataset.tipTitle,body=el.dataset.tip;if(!title&&!body)return '';return `${title?`<strong>${esc(title)}</strong>`:''}${body?`<p>${esc(body)}</p>`:''}${extra}`;}
function showTip(el){const html=tipContent(el);if(!html){hideTip();return;}tipEl.innerHTML=html;tipEl.classList.add('show');tipEl.classList.toggle('is-wide',el.dataset.tipKind==='trait');const r=el.getBoundingClientRect(),w=tipEl.offsetWidth,h=tipEl.offsetHeight;let left=r.left+r.width/2-w/2,top=r.top-h-10;if(top<8)top=r.bottom+10;if(el.closest('.trait-rail')){left=r.right+12;top=r.top+r.height/2-h/2;}if(el.closest('.equipment-rail')){left=r.left-w-12;top=r.top+r.height/2-h/2;}tipEl.style.left=`${Math.max(8,Math.min(innerWidth-w-8,left))}px`;tipEl.style.top=`${Math.max(8,Math.min(innerHeight-h-8,top))}px`;}
function hideTip(){clearTimeout(tipTimer);tipTarget=null;tipEl.classList.remove('show');}
document.addEventListener('pointerover',event=>{if(drag||event.pointerType==='touch')return;const el=event.target.closest('[data-tip],[data-tip-kind],[data-tip-title]');
 const trait=event.target.closest('.synergy[data-id],.popover-trait[data-id]'),shopCard=event.target.closest('.shop-card[data-char]');
 const scene=app.querySelector('.classic-scene');if(scene){scene.classList.toggle('trait-focus',!!trait);scene.classList.toggle('char-focus',!!shopCard);app.querySelectorAll('.roster-card').forEach(card=>{card.classList.toggle('trait-match',!!trait&&card.dataset.traits?.split(' ').includes(trait.dataset.id));card.classList.toggle('char-match',!!shopCard&&card.dataset.char===shopCard.dataset.char);});}
 if(el===tipTarget)return;clearTimeout(tipTimer);tipTarget=el;if(!el){tipEl.classList.remove('show');return;}tipTimer=setTimeout(()=>{if(tipTarget===el&&el.isConnected)showTip(el);},tipEl.classList.contains('show')?40:260);});
document.addEventListener('pointerdown',hideTip,true);
document.addEventListener('scroll',hideTip,true);
window.addEventListener('pagehide',save);
window.addEventListener('resize',fitGame);
document.addEventListener('fullscreenchange',fitGame);
save();render();if(recovered)toast('旧存档无法读取，已为你开始新的远征。');
